using U=uint64_t;using V=std::vector<uint32_t>;using Column=std::array<U,10>;
static volatile std::sig_atomic_t stopped=0;static void stop_handler(int){stopped=1;}
static void atomic_text(const std::string&path,const std::string&data){auto p=std::filesystem::path(path);if(p.has_parent_path())std::filesystem::create_directories(p.parent_path());std::ofstream f(path+".tmp");if(!f)throw std::runtime_error("cannot write");f<<data;f.close();if(!f)throw std::runtime_error("write failed");std::filesystem::rename(path+".tmp",path);}
static void write_vectors(const std::string&path,const V&v){std::ostringstream s;for(auto x:v)s<<x<<'\n';atomic_text(path,s.str());}
#include <unordered_map>
#include <set>
struct Options {std::string input,output,catalog,input_sha,baseline_sha,catalog_sha;double seconds=600,checkpoint=15;int target=92;U start=0,max_quartets=0,seed=424401;int frontier_per_row=64;std::string frontier_load;};
static Options options(int argc,char**argv){Options o;for(int k=1;k<argc;++k){std::string key=argv[k];if(k+1==argc)throw std::runtime_error("missing option value");std::string v=argv[++k];
if(key=="--input")o.input=v;else if(key=="--output")o.output=v;else if(key=="--catalog")o.catalog=v;else if(key=="--seed")o.seed=std::stoull(v);else if(key=="--frontier-per-row")o.frontier_per_row=std::stoi(v);else if(key=="--frontier-load")o.frontier_load=v;else if(key=="--seconds")o.seconds=std::stod(v);else if(key=="--target")o.target=std::stoi(v);else if(key=="--start-row")o.start=std::stoull(v);else if(key=="--max-quartets")o.max_quartets=std::stoull(v);else if(key=="--checkpoint-seconds")o.checkpoint=std::stod(v);else if(key=="--input-sha256")o.input_sha=v;else if(key=="--baseline-sha256")o.baseline_sha=v;else if(key=="--catalog-sha256")o.catalog_sha=v;else throw std::runtime_error("unknown option "+key);}
if(o.input.empty()||o.output.empty()||o.catalog.empty()||!std::isfinite(o.seconds)||o.seconds<0||!std::isfinite(o.checkpoint)||o.checkpoint<=0||o.input_sha.empty()||o.catalog_sha.empty()||o.target<0||o.frontier_per_row<1||o.frontier_per_row>4096)throw std::runtime_error("invalid options");
for(auto&s:{o.input_sha,o.baseline_sha,o.catalog_sha})if(!s.empty()&&(s.size()!=64||s.find_first_not_of("0123456789abcdef")!=std::string::npos))throw std::runtime_error("invalid hash");
return o;}
#include "kernel_quartet_optimizer.hpp"
struct FrontierEntry{U row=0,priority=0,model_key=0;std::array<int,4> circuits{};std::array<uint32_t,4> move{};int optimum_rank=0,rank=0,origin=0;V vectors;};
static U mixed(U x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
static U atom(int g,uint32_t value){return mixed((U(g)<<32)|value);}
template<class Emit>static void sample_frontier(const quartet::Bags&bags,const quartet::Bases&all,int cap,const std::chrono::steady_clock::time_point&deadline,Emit emit){unsigned present=0;for(int s=1;s<16;++s)if(bags[s].groups)present|=1U<<(s-1);int rank=quartet::present_rank(present),count=0;const std::vector<uint32_t> zero{0};
 auto candidate=[&](const quartet::Basis&basis,const std::array<uint32_t,4>&value,int origin){std::array<uint32_t,4> move{};for(int v=0;v<4;++v)for(int k=0;k<basis.size;++k)if(basis.transform[v]>>k&1)move[v]^=value[k];int score=0;for(int s=1;s<16;++s){uint32_t shifted=0;for(int bit=0;bit<4;++bit)if(s>>bit&1)shifted^=move[bit];score+=bags[s].count(shifted);}emit(move,score,origin);};
 for(const auto&basis:all[rank]){if((basis.present&present)!=basis.present)continue;const auto&a=bags[basis.classes[0]].values;const auto&b=basis.size>1?bags[basis.classes[1]].values:zero;const auto&c=basis.size>2?bags[basis.classes[2]].values:zero;const auto&d=basis.size>3?bags[basis.classes[3]].values:zero;for(auto w:a)for(auto x:b)for(auto y:c)for(auto z:d){if(count>=cap||stopped||std::chrono::steady_clock::now()>=deadline)goto xor_samples;candidate(basis,{w,x,y,z},0);++count;}}
 xor_samples: count=0;for(const auto&basis:all[rank]){if((basis.present&present)!=basis.present)continue;std::array<uint32_t,4> value{};for(int k=0;k<basis.size;++k){auto&bag=bags[basis.classes[k]];value[k]=bag.count(0)?0:bag.values.front();}for(int k=0;k<basis.size;++k){auto&bag=bags[basis.classes[k]];auto saved=value[k];for(size_t i=0;i<bag.values.size();++i)for(size_t j=i+1;j<bag.values.size();++j){auto rhs=bag.values[i]^bag.values[j];if(bag.count(rhs))continue;if(count>=16||stopped||std::chrono::steady_clock::now()>=deadline)return;value[k]=rhs;candidate(basis,value,1);++count;}value[k]=saved;}}
}
int main(int argc,char**argv){Options o;try{o=options(argc,argv);rlimit limit{768ULL*1024*1024,768ULL*1024*1024};if(setrlimit(RLIMIT_AS,&limit))throw std::runtime_error("memory limit failed");
std::ifstream in(o.input);std::string magic;int n,p,c;std::array<int,3> perm{};if(!(in>>magic>>n>>p>>c)||magic!="MMKERNELWIDE1"||n<2||n>5||p<1||p>10000||c<4||c>50000)throw std::runtime_error("invalid header");if(!(in>>perm[0]>>perm[1]>>perm[2]))throw std::runtime_error("missing permutation");auto sorted=perm;std::sort(sorted.begin(),sorted.end());if(sorted!=std::array<int,3>{0,1,2})throw std::runtime_error("invalid permutation");
int width=n*n;U bound=U(1)<<width;V baseline(p);std::vector<Column> columns(p);std::vector<std::vector<int>> rows(p);std::unordered_set<U> unique_pairs;
for(int g=0;g<p;++g){U a,b,w;if(!(in>>a>>b>>w)||!a||!b||a>=bound||b>=bound||w>=bound)throw std::runtime_error("invalid pair/model");if(!unique_pairs.insert((a<<25)|b).second)throw std::runtime_error("duplicate pair");baseline[g]=w;columns[g].fill(0);for(U x=a;x;x&=x-1)for(U y=b;y;y&=y-1){int r=__builtin_ctzll(x)*width+__builtin_ctzll(y);columns[g][r/64]^=U(1)<<(r%64);rows[g].push_back(r);}}
std::vector<std::vector<int>> supports(c);std::set<std::vector<int>> unique_supports;for(int k=0;k<c;++k){int kind,size;if(!(in>>kind>>size)||kind<0||kind>2||size<3||size>128||(kind==0&&size!=3)||(kind==1&&size!=4))throw std::runtime_error("invalid wide circuit");Column total{};std::unordered_set<int> distinct;for(int j=0;j<size;++j){int g;if(!(in>>g)||g<0||g>=p||!distinct.insert(g).second)throw std::runtime_error("invalid group");supports[k].push_back(g);for(int x=0;x<10;++x)total[x]^=columns[g][x];}if(std::any_of(total.begin(),total.end(),[](U x){return x;}))throw std::runtime_error("nonkernel circuit rejected");std::sort(supports[k].begin(),supports[k].end());if(!unique_supports.insert(supports[k]).second)throw std::runtime_error("duplicate circuit");}std::string extra;if(in>>extra)throw std::runtime_error("trailing input");
V target(width*width);for(int i=0;i<n;++i)for(int j=0;j<n;++j)for(int k=0;k<n;++k){std::array<int,3> xyz{i*n+j,j*n+k,k*n+i};target[xyz[perm[0]]*width+xyz[perm[1]]]^=uint32_t(1)<<xyz[perm[2]];}auto check=[&](const V&w){V observed(width*width);for(int g=0;g<p;++g){if(w[g]>=bound)throw std::runtime_error("mask out of range");if(w[g])for(int r:rows[g])observed[r]^=w[g];}if(observed!=target)throw std::runtime_error("original PW=Y failed");};check(baseline);
std::ifstream cat(o.catalog);U total;if(!(cat>>magic>>total)||magic!="MMKQUARTETS1"||total>2000000||o.start>total)throw std::runtime_error("invalid finite quartet catalog");std::vector<std::array<int,4>> quartets(total);std::set<std::array<int,4>> seen;for(auto&t:quartets){if(!(cat>>t[0]>>t[1]>>t[2]>>t[3])||t[0]<0||t[0]>=t[1]||t[1]>=t[2]||t[2]>=t[3]||t[3]>=c||!seen.insert(t).second)throw std::runtime_error("invalid/duplicate quartet row");}if(cat>>extra)throw std::runtime_error("trailing catalog");
int baseline_rank=std::count_if(baseline.begin(),baseline.end(),[](uint32_t x){return x;});V best=baseline;int best_rank=baseline_rank;U considered=0,bound_pruned=0,exact=0,candidates=0,workload=0,next=o.start,frontier_proposals=0;std::string status="RUNNING",reason="";auto all=quartet::make_bases();auto start=std::chrono::steady_clock::now();auto deadline=start+std::chrono::duration_cast<std::chrono::steady_clock::duration>(std::chrono::duration<double>(o.seconds));auto elapsed=[&](){return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};
std::vector<FrontierEntry> frontier;U source_key=0;for(int g=0;g<p;++g)source_key^=atom(g,baseline[g]);
auto retain=[&](U ordinal,const std::array<int,4>&t,const std::array<uint32_t,4>&move,int optimum_rank,int rank,int origin){++frontier_proposals;if(rank<optimum_rank||rank>optimum_rank+1||rank>std::min(94,baseline_rank+1))return;U model_key=source_key;bool changed=false;std::unordered_map<int,uint32_t> shifts;for(int bit=0;bit<4;++bit)for(int g:supports[t[bit]])shifts[g]^=move[bit];for(auto item:shifts)if(item.second){changed=true;model_key^=atom(item.first,baseline[item.first])^atom(item.first,baseline[item.first]^item.second);}if(!changed)return;U priority=mixed(model_key^o.seed);auto worst=std::max_element(frontier.begin(),frontier.end(),[](const auto&a,const auto&b){return a.priority<b.priority;});bool possible=frontier.size()<128||priority<worst->priority;bool duplicate_key=std::any_of(frontier.begin(),frontier.end(),[&](const auto&entry){return entry.model_key==model_key;});if(!possible&&!duplicate_key)return;V moved=baseline;for(auto item:shifts)moved[item.first]^=item.second;for(auto&entry:frontier)if(entry.model_key==model_key&&entry.vectors==moved)return;check(moved);if(std::count_if(moved.begin(),moved.end(),[](uint32_t x){return x;})!=rank)throw std::runtime_error("frontier rank mismatch");if(rank<best_rank){best_rank=rank;best=moved;}FrontierEntry entry{ordinal,priority,model_key,t,move,optimum_rank,rank,origin,moved};if(frontier.size()<128)frontier.push_back(std::move(entry));else if(possible)*worst=std::move(entry);};
if(!o.frontier_load.empty()){std::ifstream load(o.frontier_load);std::string tag,input_hash,catalog_hash;U seed,size;if(!(load>>tag>>input_hash>>catalog_hash>>seed>>size)||tag!="MMKFRONTIER1"||input_hash!=o.input_sha||catalog_hash!=o.catalog_sha||seed!=o.seed||size>128)throw std::runtime_error("frontier resume bindings mismatch");for(U n=0;n<size;++n){U row;std::array<int,4>t;std::array<uint32_t,4>move;int optimum_rank,rank,origin;if(!(load>>row>>t[0]>>t[1]>>t[2]>>t[3]>>move[0]>>move[1]>>move[2]>>move[3]>>optimum_rank>>rank>>origin)||row>=o.start||row>=total||t!=quartets[row]||std::any_of(move.begin(),move.end(),[&](uint32_t x){return x>=bound;}))throw std::runtime_error("invalid frontier resume entry");retain(row,t,move,optimum_rank,rank,origin);}if(load>>extra)throw std::runtime_error("trailing frontier resume input");}
auto checkpoint=[&](){std::sort(frontier.begin(),frontier.end(),[](const auto&a,const auto&b){return a.priority<b.priority;});std::ostringstream archive;archive<<"MMKFRONTIER1 "<<o.input_sha<<' '<<o.catalog_sha<<' '<<o.seed<<' '<<frontier.size()<<'\n';for(size_t i=0;i<frontier.size();++i){const auto&entry=frontier[i];archive<<entry.row;for(int x:entry.circuits)archive<<' '<<x;for(auto x:entry.move)archive<<' '<<x;archive<<' '<<entry.optimum_rank<<' '<<entry.rank<<' '<<entry.origin<<'\n';write_vectors(o.output+".frontier-"+std::to_string(i)+".w.txt",entry.vectors);}atomic_text(o.output+".frontier.txt",archive.str());check(best);write_vectors(o.output+".best.w.txt",best);write_vectors(o.output+".current.w.txt",best);std::ostringstream s;s<<"{\"engine\":\"exact-four-kernel-frontier-v1\",\"status\":\""<<status<<"\",\"reason\":\""<<reason<<"\",\"baseline_rank\":"<<baseline_rank<<",\"best_rank\":"<<best_rank<<",\"current_rank\":"<<best_rank<<",\"target_rank\":"<<o.target<<",\"target_reached\":"<<(best_rank<=o.target?"true":"false")<<",\"linear_exact\":true,\"tensor_invariant_checked\":true,\"full_matrix_verified\":false,\"steps\":"<<considered<<",\"quartets_total\":"<<total<<",\"quartets_considered\":"<<considered<<",\"prefix_rows_skipped\":"<<o.start<<",\"next_row\":"<<next<<",\"bound_pruned\":"<<bound_pruned<<",\"exact_evaluated\":"<<exact<<",\"full_basis_rhs_workload\":"<<workload<<",\"frontier_shortlist\":"<<frontier.size()<<",\"frontier_proposals\":"<<frontier_proposals<<",\"frontier_seed\":"<<o.seed<<",\"frontier_sampled\":true,\"candidate_assignments\":"<<candidates<<",\"elapsed_seconds\":"<<elapsed()<<",\"input_sha256\":\""<<o.input_sha<<"\",\"catalog_sha256\":\""<<o.catalog_sha<<"\",\"baseline_sha256\":\""<<o.baseline_sha<<"\"}\n";atomic_text(o.output+".stats.json",s.str());};
std::signal(SIGTERM,stop_handler);std::signal(SIGINT,stop_handler);checkpoint();double next_checkpoint=o.checkpoint;
if(best_rank<=o.target){status="MODEL_FOUND";reason="baseline already meets target";}else for(;next<total;){if(stopped||std::chrono::steady_clock::now()>=deadline||(o.max_quartets&&considered>=o.max_quartets)){status="UNKNOWN";reason=stopped?"interrupted":"wall or quartet budget";break;}auto t=quartets[next];quartet::Bags bags;std::unordered_map<int,int> memberships;for(int j=0;j<4;++j)for(int g:supports[t[j]])memberships[g]|=1<<j;for(auto entry:memberships)bags[entry.second].add(baseline[entry.first]);
int zeros=0,upper=0;for(int cl=1;cl<16;++cl){zeros+=bags[cl].zeros;upper+=bags[cl].maximum;}if(baseline_rank+zeros-upper>o.target)++bound_pruned;++exact;auto opt=quartet::optimize_components(bags,all,deadline,&stopped);candidates+=opt.candidates;workload+=opt.workload;if(!opt.complete){status="UNKNOWN";reason="interrupted inside exact quartet";break;}int optimum_rank=baseline_rank+opt.zeros-opt.score;if(optimum_rank<best_rank){best=baseline;for(int bit=0;bit<4;++bit)for(int group:supports[t[bit]])best[group]^=opt.move[bit];check(best);best_rank=optimum_rank;}bool hit=optimum_rank<=o.target;sample_frontier(bags,all,o.frontier_per_row,deadline,[&](const auto&move,int score,int origin){retain(next,t,move,optimum_rank,baseline_rank+zeros-score,origin);});

++considered;++next;if(hit){V moved=baseline;for(int j=0;j<4;++j)for(int g:supports[t[j]])moved[g]^=opt.move[j];check(moved);best_rank=std::count_if(moved.begin(),moved.end(),[](uint32_t x){return x;});if(best_rank>o.target)throw std::runtime_error("objective/rank mismatch");best=moved;std::ostringstream proof;proof<<"{\"circuit_i\":"<<t[0]<<",\"circuit_j\":"<<t[1]<<",\"circuit_k\":"<<t[2]<<",\"circuit_l\":"<<t[3]<<",\"d\":"<<opt.move[0]<<",\"e\":"<<opt.move[1]<<",\"f\":"<<opt.move[2]<<",\"g\":"<<opt.move[3]<<",\"before_rank\":"<<baseline_rank<<",\"after_rank\":"<<best_rank<<",\"linear_verified\":true}\n";atomic_text(o.output+".solution.json",proof.str());status="MODEL_FOUND";reason="pending independent global verification";break;}if(elapsed()>=next_checkpoint){checkpoint();next_checkpoint=elapsed()+o.checkpoint;}}
if(status=="RUNNING"){status="NO_TARGET";reason="finite supplied quartet suffix exhausted";}checkpoint();std::cout<<status<<" quartets="<<considered<<" best_rank="<<best_rank<<'\n';return 0;
}catch(const std::exception&e){if(!o.output.empty())try{atomic_text(o.output+".stats.json","{\"status\":\"ERROR\",\"reason\":\"native validation or IO failure\"}\n");}catch(...){}std::cerr<<"quartet_frontier_worker: "<<e.what()<<'\n';return 1;}}
